        <div v-if="showErrorDialog" class="dialog-overlay">
         <div class="dialog-content error-dialog">
            <h3>提示</h3>
            <div class="dialog-body">
                <p>该服务暂未提供</p>
            </div>
            <div class="dialog-footer">
                <button @click="confirmError" class="primary-btn">确认</button>
            </div>
        </div>
        </div>
      <h1>海量库库订单信息查询</h1>
      <div>
        <label>选择流程:
          <select v-model="selectedProcess">
            <option value="t_order_esim">esim</option>
            <option value="tf_b_preorder_broadband">宽带</option>
            <option value="TF_B_ORDER_OFFICIAL">宽带正式单</option>
            <option value="tf_b_glory_preorder">2I号卡</option>
            <option value="tf_b_glory_simple_preorder">2C号卡</option>
          </select>
        </label>
        <label>选择查询条件:
          <select v-model="selectedCondition">
            <option value="order_id">order_id</option>
            <option value="order_no">order_no</option>
          </select>
        </label>
        <label>输入查询值: <input v-model="queryValue" type="text"></label>
        <button @click="fetchOrder">查询订单</button>
      </div>
      <div v-if="order && Object.keys(order).length" class="order-container">
        <h2>订单信息</h2>
        <div class="order-info">
          <div v-for="(value, key) in order" :key="key" class="order-item">
            <div class="key">{{ key }}:</div>
            <div class="value">{{ value }}</div>
          </div>
        </div>
        <button @click="showRemarkDialog">保存订单</button>
      </div>
      <div>
        <h2>输入新订单进行比对</h2>
        <label>选择流程:
          <select v-model="newSelectedProcess">
            <option value="t_order_esim">esim</option>
            <option value="tf_b_preorder_broadband">宽带</option>
            <option value="TF_B_ORDER_OFFICIAL">宽带正式单</option>
            <option value="tf_b_glory_preorder">2I订单</option>
            <option value="tf_b_glory_simple_preorder">2C号卡</option>
          </select>
        </label>
        <label>选择查询条件:
          <select v-model="newSelectedCondition">
            <option value="order_id">order_id</option>
            <option value="order_no">order_no</option>
          </select>
        </label>
        <label>输入查询值: <input v-model="newQueryValue" type="text"></label>
        <button @click="compareOrders">比对订单</button>
      </div>
      <div v-if="comparisonResult && Object.keys(comparisonResult).length" class="order-container">
        <h2>比对结果</h2>
        <!-- 不一致的数据 -->
        <div v-if="differentResults.length > 0">
          <h3 class="comparison-subtitle">不一致的数据</h3>
          <div class="order-info">
            <div 
              v-for="item in differentResults" 
              :key="item.key" 
              class="order-item different"
            >
              <div class="key">{{ item.key }}:</div>
              <div class="value">
                <div>原始值: {{ (selectedSavedOrder || order)[item.key] }}</div>
                <div>新订单值: {{ newOrderData[item.key] }}</div>
                <div class="compare-result">不一致</div>
              </div>
            </div>
          </div>
        </div>
        <!-- 一致的数据 -->
        <div v-if="sameResults.length > 0">
          <h3 class="comparison-subtitle">一致的数据</h3>
          <div class="order-info">
            <div 
              v-for="item in sameResults" 
              :key="item.key" 
              class="order-item"
            >
              <div class="key">{{ item.key }}:</div>
              <div class="value">
                <div>原始值: {{ (selectedSavedOrder || order)[item.key] }}</div>
                <div>新订单值: {{ newOrderData[item.key] }}</div>
                <div class="compare-result">一致</div>
              </div>
            </div>
          </div>
        </div>
      </div>
  
      <div v-if="savedOrders && savedOrders.length > 0" class="order-container">
        <div class="header-actions">
          <h2>已保存的历史订单信息</h2>
          <button class="clear-btn" @click="clearHistory">清空历史记录</button>
        </div>
        <div class="saved-orders">
          <div v-for="(savedOrder, index) in savedOrders" :key="index" class="saved-order">
            <div class="saved-order-header">
              <div class="header-left">
                <h3>历史订单 #{{index + 1}}</h3>
                <button 
                  class="toggle-btn" 
                  @click="toggleOrder(index)"
                >
                  {{ isOrderCollapsed(index) ? '展开' : '收起' }}
                </button>
                <button @click="useForComparison(savedOrder)">使用此订单进行比对</button>
                <button class="delete-btn" @click="deleteSavedOrder(index)">删除</button>
              </div>
              <div class="header-right">
                <span v-if="savedOrder.备注" class="order-remark">备注: {{ savedOrder.备注 }}</span>
                <span v-if="savedOrder.savedAt" class="order-remark">保存时间: {{ savedOrder.savedAt }}</span>
              </div>
            </div>
            <div v-show="!isOrderCollapsed(index)" class="order-content">
              <div class="order-info">
                <div v-for="(value, key) in filteredOrderData(savedOrder)" :key="key" class="order-item">
                  <div class="key">{{ key }}:</div>
                  <div class="value">{{ value }}</div>
                </div>
              </div>
              <!-- <div class="order-actions">
                <button @click="useForComparison(savedOrder)">使用此订单进行比对</button>
                <button class="delete-btn" @click="deleteSavedOrder(index)">删除</button>
              </div> -->
            </div>
          </div>
        </div>
      </div>
  
      <!-- 添加弹窗组件 -->
      <div v-if="showDialog" class="dialog-overlay">
        <div class="dialog-content">
          <h3>添加流程备注</h3>
          <div class="dialog-body">
            <input 
              v-model="orderRemark" 
              type="text" 
              placeholder="请填写流程信息"
              @keyup.enter="confirmSave"
            >
          </div>
          <div class="dialog-footer">
            <button @click="cancelSave">取消</button>
            <button @click="confirmSave" class="primary-btn">完成</button>
          </div>
        </div>
      </div>
