  </template>
  
  <script>
  export default {
    name: 'PgDb',
    data() {
      return {
        // 错误弹窗
        showErrorDialog: true,
        selectedProcess: 't_order_esim',
        selectedCondition: 'order_id',
        queryValue: '',
        order: null,
        savedOrders: [],
        selectedSavedOrder: null,
        newSelectedCondition: 'order_id',
        newQueryValue: '',
        comparisonResult: null,
        newOrderData: null,
        orderRemark: '',
        showDialog: false, // 控制弹窗显示
        collapsedOrders: {}, // 保持这个对象
      };
    },
    async created() {
      await this.loadSavedOrders();
    },
    async mounted() {
      // 等待订单加载完成
      await this.loadSavedOrders();
      // 将所有订单设置为收起状态
      this.savedOrders.forEach((_, index) => {
        this.$set(this.collapsedOrders, index, true);
      });
    },
    computed: {
      newSelectedProcess: {
        get() {
          return this.selectedProcess;
        },
        set(value) {
          this.selectedProcess = value;
        }
      },
      differentResults() {
        if (!this.comparisonResult) return [];
        return Object.entries(this.comparisonResult)
          .filter(([, isSame]) => !isSame)
          .map(([key]) => ({ key }));
      },
      sameResults() {
        if (!this.comparisonResult) return [];
        return Object.entries(this.comparisonResult)
          .filter(([, isSame]) => isSame)
          .map(([key]) => ({ key }));
      }
    },
    methods: {
        // 错误弹窗
        confirmError() {
            this.showErrorDialog = false;
            this.$router.push('/'); // 点击确认后返回首页
        },
      async fetchOrder() {
        try {
          const response = await fetch(
            `http://localhost:8081/get_pgorder?process=${this.selectedProcess}&condition=${this.selectedCondition}&value=${this.queryValue}`
          );
          const data = await response.json();
          console.log('API Response:', data);
          
          if (response.ok) {
            // 确保 data 不为 null
            this.order = data || {};
            console.log('Set order data:', this.order);
          } else {
            this.order = null;
            alert(data.message || '查询失败');
          }
        } catch (error) {
          this.order = null;
          console.error('查询订单时出错:', error);
        }
      },
      async loadSavedOrders() {
        try {
          const response = await fetch('http://localhost:8081/load_pgorders');
          if (response.ok) {
            this.savedOrders = await response.json();
          } else {
            console.error('加载历史订单失败');
          }
        } catch (error) {
          console.error('加载历史订单失败:', error);
        }
      },
      async saveOrder() {
        if (this.order) {
          try {
            const orderToSave = {
              ...this.order,
              savedAt: new Date().toLocaleString(),
              备注: this.orderRemark.trim()
            };
            
            const response = await fetch('http://localhost:8081/save_pgorder', {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json'
              },
              body: JSON.stringify(orderToSave)
            });
  
            if (response.ok) {
              await this.loadSavedOrders();
              this.orderRemark = '';
              alert('订单信息已保存');
            } else {
              alert('保存订单失败');
            }
          } catch (error) {
            console.error('保存订单时出错:', error);
            alert('保存订单失败');
          }
        }
      },
      async deleteSavedOrder(index) {
        if (confirm('确定要删除这条历史订单吗？')) {
          try {
            const response = await fetch(`http://localhost:8081/delete_pgorder/${index}`, {
              method: 'DELETE'
            });
  
            if (response.ok) {
              await this.loadSavedOrders();
              if (this.selectedSavedOrder === this.savedOrders[index]) {
                this.selectedSavedOrder = null;
              }
            } else {
              alert('删除订单失败');
            }
          } catch (error) {
            console.error('删除订单时出错:', error);
            alert('删除订单失败');
          }
        }
      },
      useForComparison(savedOrder) {
        this.selectedSavedOrder = savedOrder;
        alert('已选择此订单作为比对基准');
      },
      async compareOrders() {
        try {
          const response = await fetch(
            `http://localhost:8081/get_pgorder?process=${this.newSelectedProcess}&condition=${this.newSelectedCondition}&value=${this.newQueryValue}`
          );
          const newOrder = await response.json();
          if (response.ok) {
            this.comparisonResult = {};
            const baseOrder = this.selectedSavedOrder || this.order;
            if (!baseOrder) {
              alert('请先查询要比对的订单或选择一个历史订单');
              return;
            }
            this.newOrderData = newOrder;
            for (const key in baseOrder) {
              if (Object.prototype.hasOwnProperty.call(baseOrder, key) && 
                  Object.prototype.hasOwnProperty.call(newOrder, key)) {
                this.comparisonResult[key] = baseOrder[key] === newOrder[key];
              }
            }
          } else {
            alert(newOrder.message);
          }
        } catch (error) {
          console.error('比对订单时出错:', error);
        }
      },
      async clearHistory() {
        if (confirm('确定要清空所有历史记录吗？')) {
          try {
            const response = await fetch('http://localhost:8081/clear_pgorders', {
              method: 'DELETE'
            });
  
            if (response.ok) {
              this.savedOrders = [];
              this.selectedSavedOrder = null;
            } else {
              alert('清空历史记录失败');
            }
          } catch (error) {
            console.error('清空历史记录时出错:', error);
            alert('清空历史记录失败');
          }
        }
      },
      // 显示备注弹窗
      showRemarkDialog() {
        this.showDialog = true;
        this.orderRemark = ''; // 清空之前的备注
      },
  
      // 取消保存
      cancelSave() {
        this.showDialog = false;
        this.orderRemark = '';
      },
  
      // 确认保存
      async confirmSave() {
        if (!this.orderRemark.trim()) {
          alert('请填写流程信息');
          return;
        }
        await this.saveOrder();
        this.showDialog = false;
      },
  
      // 修改过滤订单数据的方法
      filteredOrderData(order) {
        // eslint-disable-next-line no-unused-vars
        const { 备注: _备注, ...filteredOrder } = { ...order };
        return filteredOrder;
      },
  
      // 修改切换方法
      toggleOrder(index) {
        this.$set(this.collapsedOrders, index, !this.collapsedOrders[index]);
      },
  
      // 修改检查方法
      isOrderCollapsed(index) {
        // 如果状态未设置，默认返回 true（收起状态）
        return this.collapsedOrders[index] !== false;
      },
    }
  };
  </script>
  
