    <!-- 比对按钮 -->
    <div class="comparison-actions">
      <button 
        v-if="!showSecondInput" 
        @click="startComparison" 
        class="compare-btn"
        :disabled="!isValidJson(firstJson)"
      >
        输入第二个json
      </button>
      <button 
        v-else 
        @click="compareJsons" 
        class="compare-btn"
        :disabled="!isValidJson(firstJson) || !isValidJson(secondJson)"
      >
        执行比对
      </button>
