<script>
import JsonViewer from 'vue-json-viewer'

export default {
  name: 'JsonComparison',
  components: {
    JsonViewer
  },
  data() {
    return {
      firstJson: '',
      secondJson: '',
      formattedFirstJson: '',
      formattedSecondJson: '',
      parsedFirstJson: null,
      parsedSecondJson: null,
      showSecondInput: false,
      comparisonResult: null,
      firstJsonError: '',
      secondJsonError: '',
      firstJsonErrorLine: null,
      secondJsonErrorLine: null
    }
  },
  computed: {
    firstJsonLines() {
      return this.firstJson.split('\n')
    },
    secondJsonLines() {
      return this.secondJson.split('\n')
    }
  },
  methods: {
    formatFirstJson() {
      this.formattedFirstJson = this.firstJson
      try {
        const parsed = JSON.parse(this.firstJson)
        this.parsedFirstJson = parsed
        this.firstJsonError = ''
        this.firstJsonErrorLine = null
      } catch (e) {
        this.parsedFirstJson = null
        this.firstJsonError = this.getErrorMessage(e)
        this.firstJsonErrorLine = this.getErrorLine(e, this.firstJson)
      }
    },
    formatSecondJson() {
      this.formattedSecondJson = this.secondJson
      try {
        const parsed = JSON.parse(this.secondJson)
        this.parsedSecondJson = parsed
        this.secondJsonError = ''
        this.secondJsonErrorLine = null
      } catch (e) {
        this.parsedSecondJson = null
        this.secondJsonError = this.getErrorMessage(e)
        this.secondJsonErrorLine = this.getErrorLine(e, this.secondJson)
      }
    },
    getErrorMessage(error) {
      if (!this.firstJson && !this.secondJson) return ''
      
      const message = error.message
      if (message.includes('Unexpected token')) {
        return 'JSON格式错误：存在非法字符'
      } else if (message.includes('Unexpected end')) {
        return 'JSON格式错误：JSON不完整'
      } else if (message.includes('Unexpected number')) {
        return 'JSON格式错误：数字格式不正确'
      } else if (message.includes('Unexpected string')) {
        return 'JSON格式错误：字符串格式不正确'
      } else {
        return 'JSON格式错误：' + message
      }
    },
    getErrorLine(error, json) {
      const message = error.message
      const match = message.match(/position (\d+)/)
      if (match) {
        const position = parseInt(match[1])
        const lines = json.slice(0, position).split('\n')
        return lines.length
      }
      return null
    },
    scrollToError(refName) {
      this.$nextTick(() => {
        const textarea = this.$refs[refName]
        if (textarea) {
          const lineHeight = 24 // 与CSS中的line-height对应
          const errorLine = refName === 'firstJsonInput' ? this.firstJsonErrorLine : this.secondJsonErrorLine
          if (errorLine) {
            const scrollTop = (errorLine - 1) * lineHeight - textarea.clientHeight / 2
            textarea.scrollTop = Math.max(0, scrollTop)
          }
        }
      })
    },
    isValidJson(json) {
      try {
        JSON.parse(json)
        return true
      } catch (e) {
        return false
      }
    },
    startComparison() {
      if (this.isValidJson(this.firstJson)) {
        this.showSecondInput = true
      }
    },
    compareJsons() {
      if (!this.isValidJson(this.firstJson) || !this.isValidJson(this.secondJson)) {
        return
      }

      const obj1 = JSON.parse(this.firstJson)
      const obj2 = JSON.parse(this.secondJson)
      
      const result = this.findDifferences(obj1, obj2)
      if (Object.keys(result).length === 0) {
        this.comparisonResult = "完全一致"
      } else {
        this.comparisonResult = result
      }
    },
    findDifferences(obj1, obj2, path = '') {
      const result = {}
      
      // 获取所有键
      const allKeys = new Set([...Object.keys(obj1), ...Object.keys(obj2)])
      
      for (const key of allKeys) {
        const currentPath = path ? `${path}.${key}` : key
        
        if (!(key in obj1)) {
          result[key] = { 
            type: '第一个json中缺少该字段',
            first: '空',
            second: obj2[key]
          }
        } else if (!(key in obj2)) {
          result[key] = { 
            type: '第二个json中缺少该字段',
            first: obj1[key],
            second: '空'
          }
        } else if (JSON.stringify(obj1[key]) !== JSON.stringify(obj2[key])) {
          if (typeof obj1[key] === 'object' && obj1[key] !== null &&
              typeof obj2[key] === 'object' && obj2[key] !== null) {
            result[key] = this.findDifferences(obj1[key], obj2[key], currentPath)
          } else {
                result[key] = {
                  type: '不一致',
                  first: obj1[key],
                  second: obj2[key]
                }
          }
        }
      }
      
      return result
    },
    syncScroll(e, which) {
      // 让pre和textarea和行号同步滚动
      const wrapper = which === 'first' ? this.$el.querySelector('.code-input-wrapper') : null
      if (wrapper) {
        const pre = wrapper.querySelector('.code-highlight')
        pre.scrollTop = e.target.scrollTop
        pre.scrollLeft = e.target.scrollLeft
        const lineNumbers = this.$refs.firstLineNumbers
        if (lineNumbers) {
          lineNumbers.scrollTop = e.target.scrollTop
        }
      }
    }
  }
}
</script>

